def bfs(start,end):
    seen={start}; q=[start]
    parent={}
    idx=0
    while idx<len(q):
        u=q[idx]; idx+=1
        if u==end: break
        for n_,d_ in ((u[0]+1,u[1]),(u[0]-1,u[1]),(u[0],u[1]+1),(u[0],u[1]-1)):
            if 0<=n_<13 and 0<=d_<6 and (n_,d_) not in seen and I[n_][d_]==2:
                seen.add((n_,d_)); parent[(n_,d_)]=u; q.append((n_,d_))
    return parent
