# Hypothesis: recolored iff there exist two markers at EQUAL manhattan distance (strictly the minimum, i.e. unique tie) 
def pred(i,j,g,marks):
    ds={m:abs(i-m[0])+abs(j-m[1]) for m in marks}
    mn=min(ds.values())
    ties=[m for m,d in ds.items() if d==mn]
    # require exactly 2 tied markers
    return len(ties)==2
